# Let's create a simple test to verify the compatibility approach
from langfuse import get_client

# Create a mock context that wraps the client
class LangfuseContextCompat:
    """Compatibility wrapper for Langfuse v3 langfuse_context API in v4"""

    def __init__(self):
        self._client = get_client()

    def update_current_observation(self, model=None, **kwargs):
        """Update current observation (generation/span)"""
        self._client.update_current_generation(model=model, **kwargs)

    def update_current_trace(self, session_id=None, tags=None, metadata=None, **kwargs):
        """Update current trace - in v4, we update the current span with metadata"""
        # Combine session_id and tags into metadata
        merged_metadata = metadata or {}
        if session_id:
            merged_metadata['session_id'] = session_id
        if tags:
            merged_metadata['tags'] = tags
        self._client.update_current_span(metadata=merged_metadata, **kwargs)

    def get_current_trace_id(self):
        """Get current trace ID"""
        return self._client.get_current_trace_id()

# Test it
langfuse_context = LangfuseContextCompat()
print("Compatibility wrapper created successfully")
print(f"Has update_current_observation: {hasattr(langfuse_context, 'update_current_observation')}")
print(f"Has update_current_trace: {hasattr(langfuse_context, 'update_current_trace')}")
print(f"Has get_current_trace_id: {hasattr(langfuse_context, 'get_current_trace_id')}")
